var v = 343;
var vs = p.speed;
var f0 = p.freq;
var loop = 3.0;
var Te = 0.3;
var tau = t % loop;
var Wm = Math.max(v, vs) * loop * 1.08;
var x0 = 16;
var sc = (W - 32) / Wm;
var y0 = H * 0.55;

ctx.font = '12px ui-sans-serif, system-ui, sans-serif';
ctx.lineWidth = 1;

// road line
ctx.strokeStyle = C.faint;
ctx.beginPath();
ctx.moveTo(0, y0 + 46);
ctx.lineTo(W, y0 + 46);
ctx.stroke();

// wavefronts
ctx.strokeStyle = C.rule;
for (var k = 0; k * Te <= tau; k++) {
  var te = k * Te;
  var r = v * (tau - te) * sc;
  var cx = x0 + vs * te * sc;
  if (r < 0.5) continue;
  ctx.beginPath();
  ctx.arc(cx, y0, r, 0, Math.PI * 2);
  ctx.stroke();
}

var sxNow = x0 + vs * tau * sc;

// Mach cone
if (vs > v) {
  var th = Math.asin(v / vs);
  var L = W;
  ctx.strokeStyle = C.accent;
  ctx.lineWidth = 1.5;
  ctx.beginPath();
  ctx.moveTo(sxNow, y0);
  ctx.lineTo(sxNow - L * Math.cos(th), y0 - L * Math.sin(th));
  ctx.moveTo(sxNow, y0);
  ctx.lineTo(sxNow - L * Math.cos(th), y0 + L * Math.sin(th));
  ctx.stroke();
  ctx.lineWidth = 1;
  ctx.fillStyle = C.accent;
  ctx.fillText('shock cone', 14, 18);
}

// source
ctx.fillStyle = C.accent;
ctx.beginPath();
ctx.arc(sxNow, y0, 5, 0, Math.PI * 2);
ctx.fill();
ctx.fillStyle = C.ink;
ctx.fillText('source', sxNow - 18, y0 - 10);

// listeners
ctx.fillStyle = C.figure;
ctx.beginPath();
ctx.arc(W - 12, y0, 4, 0, Math.PI * 2);
ctx.fill();
ctx.beginPath();
ctx.arc(10, y0, 4, 0, Math.PI * 2);
ctx.fill();
ctx.fillStyle = C.ink;
ctx.fillText('ahead', W - 52, y0 + 22);
ctx.fillText('behind', 6, y0 + 22);

if (vs < v) {
  var fA = f0 * v / (v - vs);
  var fB = f0 * v / (v + vs);
  out.note = 'ahead ' + fA.toFixed(1) + ' Hz, behind ' + fB.toFixed(1) + ' Hz, true ' + f0.toFixed(0) + ' Hz';
} else if (vs === v) {
  out.note = 'Mach 1.00: every crest arrives at once, the fronts touch at the source';
} else {
  var thh = Math.asin(v / vs) * 180 / Math.PI;
  out.note = 'Mach ' + (vs / v).toFixed(2) + ', cone half-angle ' + thh.toFixed(1) + ' degrees, no sound ahead';
}

var v = 343;
var vs = p.speed;
var T = 1;
var y0 = H * 0.5;
var Wm = 2 * v * T * 2.25;
var sc = (W - 24) / Wm;
var cx0 = W / 2 - vs * T * sc;

ctx.font = '12px ui-sans-serif, system-ui, sans-serif';
ctx.lineWidth = 1;

// axis
ctx.strokeStyle = C.faint;
ctx.beginPath();
ctx.moveTo(0, y0);
ctx.lineTo(W, y0);
ctx.stroke();

// three crests: emitted at 0, T, 2T ; now is 2T
var i;
for (i = 0; i < 3; i++) {
  var r = v * (2 - i) * T * sc;
  var cx = cx0 + vs * i * T * sc;
  ctx.strokeStyle = i === 2 ? C.accent : C.rule;
  ctx.beginPath();
  ctx.arc(cx, y0, Math.max(r, 1), 0, Math.PI * 2);
  ctx.stroke();
  ctx.fillStyle = C.figure;
  ctx.beginPath();
  ctx.arc(cx, y0, 2.5, 0, Math.PI * 2);
  ctx.fill();
}

// source now
var sxNow = cx0 + vs * 2 * T * sc;
ctx.fillStyle = C.accent;
ctx.beginPath();
ctx.arc(sxNow, y0, 5, 0, Math.PI * 2);
ctx.fill();
ctx.fillStyle = C.ink;
ctx.fillText('source now', sxNow - 30, y0 - 12);

// ahead gap markers
var aheadOuter = sxNow + (v * T - vs * T) * sc;
var yA = y0 + 34;
ctx.strokeStyle = C.figure;
ctx.beginPath();
ctx.moveTo(sxNow, y0);
ctx.lineTo(sxNow, yA + 6);
ctx.moveTo(aheadOuter, y0);
ctx.lineTo(aheadOuter, yA + 6);
ctx.moveTo(sxNow, yA);
ctx.lineTo(aheadOuter, yA);
ctx.stroke();
ctx.fillStyle = C.ink;
ctx.fillText('ahead: (v - vs)T = ' + ((v - vs) * T).toFixed(0) + ' m', sxNow - 20, yA + 20);

// behind gap markers
var behindOuter = sxNow - (v * T + vs * T) * sc;
var yB = y0 - 40;
ctx.strokeStyle = C.figure;
ctx.beginPath();
ctx.moveTo(sxNow, y0);
ctx.lineTo(sxNow, yB - 6);
ctx.moveTo(behindOuter, y0);
ctx.lineTo(behindOuter, yB - 6);
ctx.moveTo(sxNow, yB);
ctx.lineTo(behindOuter, yB);
ctx.stroke();
ctx.fillStyle = C.ink;
ctx.fillText('behind: (v + vs)T = ' + ((v + vs) * T).toFixed(0) + ' m', behindOuter + 8, yB - 10);

ctx.fillStyle = C.faint;
ctx.fillText('drawn for T = 1 s, v = 343 m/s', 8, H - 8);

out.note = 'source speed ' + vs.toFixed(0) + ' m/s: wavelength ahead ' + ((v - vs) * T).toFixed(0) + ' m, behind ' + ((v + vs) * T).toFixed(0) + ' m';

var v = 343;
var vb = p.vb;
var vw = p.vw;
var f0 = p.f0 * 1000;
var f1 = f0 * (v + vw) / (v - vb);
var f2 = f1 * (v + vb) / (v - vw);

ctx.font = '12px ui-sans-serif, system-ui, sans-serif';
ctx.lineWidth = 1;

var xB = W * 0.12;
var xW = W * 0.86;
var y0 = H * 0.46;

// wall
ctx.strokeStyle = C.ink;
ctx.lineWidth = 2;
ctx.beginPath();
ctx.moveTo(xW, y0 - 60);
ctx.lineTo(xW, y0 + 60);
ctx.stroke();
ctx.lineWidth = 1;
ctx.fillStyle = C.ink;
ctx.fillText('wall', xW - 12, y0 - 70);

// bat
ctx.fillStyle = C.accent;
ctx.beginPath();
ctx.arc(xB, y0, 6, 0, Math.PI * 2);
ctx.fill();
ctx.fillStyle = C.ink;
ctx.fillText('bat', xB - 8, y0 - 16);

// motion arrows
function arrow(x, y, dx) {
  var s = dx > 0 ? 1 : -1;
  ctx.strokeStyle = C.figure;
  ctx.beginPath();
  ctx.moveTo(x, y);
  ctx.lineTo(x + dx, y);
  ctx.lineTo(x + dx - s * 5, y - 4);
  ctx.moveTo(x + dx, y);
  ctx.lineTo(x + dx - s * 5, y + 4);
  ctx.stroke();
}
if (vb > 0) arrow(xB + 10, y0 + 18, 22);
if (vw !== 0) arrow(xW - 10, y0 + 18, vw > 0 ? -22 : 22);

// outgoing crests (upper half), incoming crests (lower half)
var lamOut = Math.max((v - vb) / f0, 1e-6);
var lamIn = Math.max((v - vw) / f1, 1e-6);
var span = xW - xB - 18;
var nOut = 9;
var nIn = 9;
var phase = (t * 0.9) % 1;
var i, x;
ctx.strokeStyle = C.rule;
for (i = 0; i < nOut; i++) {
  x = xB + 14 + ((i + phase) / nOut) * span;
  ctx.beginPath();
  ctx.moveTo(x, y0 - 8);
  ctx.lineTo(x, y0 - 44);
  ctx.stroke();
}
for (i = 0; i < nIn; i++) {
  x = xW - 6 - ((i + phase) / nIn) * span;
  ctx.beginPath();
  ctx.moveTo(x, y0 + 8);
  ctx.lineTo(x, y0 + 44);
  ctx.stroke();
}

ctx.fillStyle = C.ink;
ctx.fillText('out: ' + (f0 / 1000).toFixed(1) + ' kHz leaves, ' + (f1 / 1000).toFixed(2) + ' kHz arrives at the wall', xB + 6, y0 - 52);
ctx.fillText('back: wall re-emits ' + (f1 / 1000).toFixed(2) + ' kHz, bat hears ' + (f2 / 1000).toFixed(2) + ' kHz', xB + 6, y0 + 62);

out.note = 'echo ' + f2.toFixed(1) + ' Hz against call ' + f0.toFixed(0) + ' Hz, beat ' + (f2 - f0).toFixed(1) + ' Hz';
